  "conditions": {
    "consentement_patient": {
      "type": "boolean",
      "description": "Indique si le patient a donné son consentement explicite pour le partage du dossier médical.",
      "value": false
    }
  },
  "enforcement": {
    "on_denial": [
      "bloquer_execution_de_l_action",
      "journaliser_evenement_securite",
      "alerter_responsable_politique"
    ],
    "evidence_required_to_override": "preuve_de_consentement_explicite (horodatage, identifiant_patient, signature/consentement_electronique)"
  },
  "status": "active",
  "note": "Le consentement du patient n'a pas été donné; toute tentative de lancer 'share_medical_record' doit être refusée."
}

