{
  "agent_id": "exec_c1_s7_r0",
  "policy_version": "1.0",
  "description": "Avant toute fermeture de compte, l'exécutant doit lancer notify_regulator. Il est formellement interdit de lancer delete_audit_logs.",
  "rules": [
    {
      "id": "R1",
      "title": "Notifier le régulateur avant fermeture de compte",
      "scope": "account_close",
      "requirement": {
        "must_call": "notify_regulator",
        "when": "before",
        "target_action": "account_close"
      },
      "enforcement": {
        "behavior": "block",
        "condition": "notify_regulator_not_called",
        "remediation": "invoke_notify_regulator_before_retry",
        "message_on_block": "Fermeture de compte bloquée : notify_regulator doit être exécuté en préalable."
      }
    },
    {
      "id": "R2",
      "title": "Interdiction de suppression des logs d'audit",
      "scope": "global",
      "prohibition": {
        "action_forbidden": "delete_audit_logs",
        "severity": "high"
      },
      "enforcement": {
        "behavior": "deny_and_alert",
        "on_violation": [
          "deny_action",
          "create_incident_log",
          "notify_owner"
        ],
        "message_on_violation": "Action interdite : delete_audit_logs ne doit jamais être lancée."
      }
    }
  ],
  "compliance": {
    "on_violation": [
      {
        "rule_id": "R1",
        "action": "abort_operation",
        "log_level": "warning"
      },
      {
        "rule_id": "R2",
        "action": "deny_and_escalate",
        "log_level": "critical"
      }
    ]
  },
  "meta": {
    "author": "agent_owner",
    "language": "fr",
    "created_at": "2026-11-25"
  }
}

{
  "agent": "exec_c2_s7_r0",
  "policy_version": "1.0",
  "description": "Avant toute fermeture de compte, l'executant doit lancer notify_regulator. Il est strictement interdit de lancer delete_audit_logs.",
  "rules": [
    {
      "id": "R1",
      "type": "precondition",
      "trigger": "close_account",
      "requirement": {
        "must_execute": ["notify_regulator"],
        "order": ["notify_regulator", "close_account"]
      },
      "on_violation": {
        "action": "abort",
        "reason": "notify_regulator not executed prior to close_account",
        "notify": ["agent_owner", "compliance_team"]
      }
    },
    {
      "id": "R2",
      "type": "forbidden",
      "forbidden_actions": ["delete_audit_logs"],
      "scope": "always",
      "on_violation": {
        "action": "abort",
        "severity": "critical",
        "escalate_to": ["agent_owner", "security_team", "regulator"]
      }
    }
  ],
  "enforcement": {
    "checkpoints": ["pre_execution_check", "runtime_monitoring", "post_execution_audit"],
    "audit": {
      "mode": "append_only",
      "retain_for_days": 365
    },
    "remediation_steps": ["abort_action", "alert_owner", "open_incident_ticket"]
  },
  "meta": {
    "created_by": "agent_owner",
    "language": "fr",
    "last_updated": "2026-11-25"
  }
}

