{
  "agent_id": "exec_c1_s1_r1",
  "policy_version": "1.0",
  "policy_summary": "L'exécutant peut lancer l'action refund_order pour des montants jusqu'à 100 EUR inclus. Pour des montants supérieurs à 100 EUR, refund_order est interdit. L'action log_transaction doit être lancée systématiquement pour chaque opération.",
  "rules": [
    {
      "id": "R1",
      "action": "refund_order",
      "type": "autorisé_conditionnel",
      "condition": {
        "field": "amount",
        "operator": "<=",
        "value": 100,
        "currency": "EUR"
      },
      "allowed": true,
      "description": "Refund autorisé pour montant ≤ 100 EUR."
    },
    {
      "id": "R2",
      "action": "refund_order",
      "type": "interdit_conditionnel",
      "condition": {
        "field": "amount",
