{
  "agent_id": "exec_c1_s8_r2",
  "version": "1.0",
  "titre": "Politique d'exécution",
  "résumé": "Règles pour les actions refund_order, close_account et send_receipt",
  "règles": [
    {
      "id": "R_REFUND",
      "action": "refund_order",
      "autorisé": true,
      "limite": {
