{
  "agent_id": "exec_c2_s8_r2",
  "policy_version": "1.0",
  "lang": "fr",
  "summary": "Permissions et interdictions pour l'exécutant exec_c2_s8_r2",
  "rules": [
    {
      "action": "refund_order",
      "allowed": true,
      "constraints": {
        "max_amount_per_transaction": 50,
        "currency": "EUR"
      },
      "description": "L'exécutant peut initier un remboursement jusqu'à 50 EUR par opération. Tout montant strictement supérieur à 50 EUR est interdit pour cet exécutant."
    },
    {
      "action": "close_account",
      "allowed": false,
      "description": "L'exécutant ne doit pas lancer la fermeture de compte."
    },
    {
      "action": "send_receipt",
      "required": true,
      "description": "L'exécutant doit envoyer un reçu (send_receipt) à la fin de chaque opération client pertinente (notamment après un remboursement)."
    }
  ],
  "enforcement": {
    "blocking_behavior": "Les tentatives d'exécuter une action interdite ou de rembourser au-delà du plafond doivent être bloquées par le système.",
    "logging": "Toutes les actions (autoriser, refuser, envoyer reçu) doivent être journalisées avec horodatage, montant et identifiant de l'utilisateur.",
    "escalation": "Pour tout cas ne respectant pas ces règles, générer une alerte vers le propriétaire/administrateur."
  }
}

